insert into public.boats (slug, name, model_name, tagline, description, long_description, length_m, beam_m, guests, guests_night, cabins, type, brand, build_year, refit_year, base_harbour, cruise_knots, max_knots, engines, stabilizers, consumption, price_from, price_high, currency, what_included, specs, gallery, highlights, hero_image, pdf_url, featured, sort_order, is_published, meta_title, meta_description) values
  ('ariyas-sunseeker-predator-84', 'Ariyas', 'Sunseeker Predator 84', 'Noble power that embodies the most sublime distinction in each outing.', 'Noble and virtuous, Ariyas is a symbol — a reminder to live nobly and embrace every adventure. Sleek lines, opulent finish, composure on the water.', 'Ample sunbathing areas, an elegant outdoor dining space and a flybridge built for sunsets. Inside, classicism and sophistication enhance an unmistakable atmosphere of exclusivity and comfort.', 27.45, 6.5, 12, 8, 4, 'motor_yacht', 'Sunseeker', 2010, 2024, 'Marina Botafoc, Ibiza', 25, 34, '2 × 2,434 hp Diesel MTU', 'ABT Vinum', '600 l/h', 7650, 8750, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"27.45 m / 6.50 m"},{"label":"Engines","value":"2 × 2,434 hp Diesel MTU"},{"label":"Cruise / max","value":"25 / 34 knots"},{"label":"Consumption","value":"600 l/h"},{"label":"Stabilizers","value":"ABT Vinum"},{"label":"Comfort","value":"Generator, A/C, Water maker, Hydraulic platform, Wifi, Bose"}]'::jsonb, '[{"src":"/images/boats/ariyas-hero.jpg","alt":"Ariyas — Sunseeker Predator 84"}]'::jsonb, '[{"icon":"length","label":"Length","value":"27.45 m"},{"icon":"guests","label":"Guests","value":"12 day · 8 night"},{"icon":"cabins","label":"Cabins","value":"2 doubles + 2 twin"},{"icon":"speed","label":"Max speed","value":"34 kn"},{"icon":"year","label":"Refit","value":"2024"}]'::jsonb, '/images/boats/ariyas-hero.jpg', null, true, 1, true, 'Ariyas — Sunseeker Predator 84 charter Ibiza', 'Charter Ariyas, a 27 m Sunseeker Predator 84 from Marina Botafoc Ibiza. Up to 12 guests, 34 kn max, refit 2024. From €7,650/day + VAT.'),
  ('belisa-mangusta-108', 'Belisa', 'Mangusta 108', 'Slender, beautiful lines of timeless elegance that captivate all the senses.', 'Belisa is the maxi-open Mangusta in its most distilled form — long, low, fast, and finished to a standard that makes a quiet impression.', 'Five bathrooms, a master plus two VIP cabins and a quadruple stateroom, Seakeeper 35 stabilization, Starlink wifi and a sound system the owner calls the best he has ever heard. A 33-metre presence at Ibiza speed.', 32.92, 7.15, 12, 10, 4, 'motor_yacht', 'Mangusta', 2008, 2023, 'Marina Botafoc, Ibiza', 28, 36, '2 × 2,800 hp Diesel MTU', 'Seakeeper 35 (the largest)', '990 l/h', 11000, 13750, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"32.92 m / 7.15 m"},{"label":"Engines","value":"2 × 2,800 hp Diesel MTU (overhaul 2022)"},{"label":"Cruise / max","value":"28 / 36 knots"},{"label":"Consumption","value":"990 l/h"},{"label":"Stabilizers","value":"Seakeeper 35"},{"label":"Comfort","value":"Generator, A/C, Water maker, Starlink wifi, Premium sound"}]'::jsonb, '[{"src":"/images/boats/belisa-hero.jpg","alt":"Belisa — Mangusta 108"}]'::jsonb, '[{"icon":"length","label":"Length","value":"32.92 m"},{"icon":"guests","label":"Guests","value":"12 day · 10 night"},{"icon":"cabins","label":"Cabins","value":"1 master · 2 VIP · 1 quadruple"},{"icon":"speed","label":"Max speed","value":"36 kn"},{"icon":"year","label":"Refit","value":"2023"}]'::jsonb, '/images/boats/belisa-hero.jpg', null, true, 2, true, 'Belisa — Mangusta 108 charter Ibiza', 'Charter Belisa, a 32.9 m Mangusta 108 maxi-open from Marina Botafoc. 12 guests, 10 overnight, 36 kn. From €11,000/day + VAT.'),
  ('chloe-princess-v58', 'Chloe', 'Princess V58', 'A silhouette that dazzles, a name that enchants — where style meets the sea.', 'An approachable, elegant Princess sport cruiser for groups who want a refined day on the water without going superyacht.', 'Chloe sits at the sweet spot of the Princess line — Volvo IPS power, three guest cabins, and the kind of finishing that makes overnight stays in Santa Eulària feel like a small private hotel.', 18.42, 4.65, 12, 6, 3, 'motor_yacht', 'Princess', 2018, null, 'Santa Eulària, Ibiza', 22, 36, '2 × 900 hp Diesel Volvo', null, '220 l/h', 3600, 4200, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"18.42 m / 4.65 m"},{"label":"Engines","value":"2 × 900 hp Diesel Volvo"},{"label":"Cruise / max","value":"22 / 36 knots"},{"label":"Consumption","value":"220 l/h"},{"label":"Base","value":"Santa Eulària, Ibiza"},{"label":"Comfort","value":"Generator, A/C, Wifi, Bose surround"}]'::jsonb, '[{"src":"/images/boats/chloe-hero.jpg","alt":"Chloe — Princess V58"}]'::jsonb, '[{"icon":"length","label":"Length","value":"18.42 m"},{"icon":"guests","label":"Guests","value":"12 day · 6 night"},{"icon":"cabins","label":"Cabins","value":"2 doubles + 1 twin"},{"icon":"speed","label":"Max speed","value":"36 kn"},{"icon":"year","label":"Year","value":"2018"}]'::jsonb, '/images/boats/chloe-hero.jpg', null, false, 3, true, 'Chloe — Princess V58 charter Ibiza', 'Charter Chloe, a Princess V58 from Santa Eulària. 18.4 m, 12 guests, 36 kn. From €3,600/day + VAT.'),
  ('dr-no-pershing-6x', 'Dr. No', 'Pershing 6X', 'Your James Bond escape on the water — thrill, speed, style of a true icon.', 'Brand-new 2025 Pershing 6X — the most performance-focused boat in the fleet. 48-knot top end from a 19-metre, three-cabin hull.', 'Pershing''s 6X is a clean-sheet design built around carbon, weight reduction and a refined hull. With MAN diesels at 1,550 hp each it delivers a cinematic 48-knot run, while Seakeeper NG5 stabilization keeps things composed at anchor.', 18.94, 4.8, 12, 6, 3, 'motor_yacht', 'Pershing', 2025, null, 'Marina Botafoc, Ibiza', 40, 48, '2 × 1,550 hp Diesel MAN', 'Seakeeper NG5', '490 l/h', 5400, 6400, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"18.94 m / 4.80 m"},{"label":"Engines","value":"2 × 1,550 hp Diesel MAN"},{"label":"Cruise / max","value":"40 / 48 knots"},{"label":"Consumption","value":"490 l/h"},{"label":"Stabilizers","value":"Seakeeper NG5"},{"label":"Comfort","value":"Generator, A/C, Water maker, Wifi, HIFI with subwoofer"}]'::jsonb, '[{"src":"/images/boats/dr-no-hero.jpg","alt":"Dr. No — Pershing 6X"}]'::jsonb, '[{"icon":"length","label":"Length","value":"18.94 m"},{"icon":"guests","label":"Guests","value":"12 day · 6 night"},{"icon":"cabins","label":"Cabins","value":"2 doubles + 1 twin"},{"icon":"speed","label":"Max speed","value":"48 kn"},{"icon":"year","label":"Year","value":"2025"}]'::jsonb, '/images/boats/dr-no-hero.jpg', null, true, 4, true, 'Dr. No — Pershing 6X charter Ibiza', 'Charter Dr. No, the brand-new 2025 Pershing 6X from Marina Botafoc. 19 m, 48 kn, three cabins. From €5,400/day + VAT.'),
  ('ella-riva-argo-90', 'Ella', 'Riva Argo 90', 'A masterpiece of navigation — sophistication and distinction on the high seas.', 'The Riva Argo 90 in its 2020 incarnation: four double cabins, five bathrooms, MTU diesels and Riva''s unmistakable hand-finished interior.', 'Ella is a 28-metre Riva — the silhouette people stop to photograph at the pontoon. Seakeeper + Sidepower fins for zero-roll at anchor, Starlink wifi and what the owner describes as the best sound system at sea.', 28.7, 6.5, 12, 8, 4, 'motor_yacht', 'Riva', 2020, null, 'Marina Botafoc, Ibiza', 22, 28, '2 × 2,650 hp Diesel MTU', 'Seakeeper + Sidepower fins', '760 l/h', 12950, 14950, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"28.70 m / 6.50 m"},{"label":"Engines","value":"2 × 2,650 hp Diesel MTU"},{"label":"Cruise / max","value":"22 / 28 knots"},{"label":"Consumption","value":"760 l/h"},{"label":"Stabilizers","value":"Seakeeper + Sidepower fins"},{"label":"Comfort","value":"Generator, A/C, Water maker, Starlink wifi, Premium sound"}]'::jsonb, '[{"src":"/images/boats/ella-hero.jpg","alt":"Ella — Riva Argo 90"}]'::jsonb, '[{"icon":"length","label":"Length","value":"28.70 m"},{"icon":"guests","label":"Guests","value":"12 day · 8 night"},{"icon":"cabins","label":"Cabins","value":"4 doubles"},{"icon":"speed","label":"Max speed","value":"28 kn"},{"icon":"year","label":"Year","value":"2020"}]'::jsonb, '/images/boats/ella-hero.jpg', null, true, 5, true, 'Ella — Riva Argo 90 charter Ibiza', 'Charter Ella, a 28.7 m Riva Argo 90 from Marina Botafoc. 12 guests, 8 overnight, 4 doubles. From €12,950/day + VAT.'),
  ('eternity-44-arcadia-85', 'Eternity 44', 'Arcadia 85', 'A sanctuary at sea, where space becomes experience.', 'The Arcadia 85 trades top-end speed for vast glazed interiors, solar panels and a serenity that catamarans and motor yachts both envy.', '27 metres, four en-suite cabins, full-height glass on three sides and a flybridge that rivals a beach club. Twin 730 hp MAN diesels are sized for displacement comfort, not noise — 200 l/h at a 13-knot cruise.', 27, 7.1, 12, 8, 4, 'motor_yacht', 'Arcadia', 2018, null, 'IGY Ibiza Marina', 13, null, '2 × 730 hp Diesel MAN', 'Zero-speed fin stabilizers', '200 l/h', 8500, 9500, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"27.00 m / 7.10 m"},{"label":"Engines","value":"2 × 730 hp Diesel MAN"},{"label":"Cruise","value":"13 knots"},{"label":"Consumption","value":"200 l/h"},{"label":"Stabilizers","value":"Zero-speed fin stabilizers"},{"label":"Comfort","value":"Solar panels, Generator, A/C, Water maker, Wifi, Bose"}]'::jsonb, '[{"src":"/images/boats/eternity-hero.jpg","alt":"Eternity 44 — Arcadia 85"}]'::jsonb, '[{"icon":"length","label":"Length","value":"27.00 m"},{"icon":"guests","label":"Guests","value":"12 day · 8 night"},{"icon":"cabins","label":"Cabins","value":"2 doubles + 2 twins"},{"icon":"speed","label":"Cruise","value":"13 kn (200 l/h)"},{"icon":"anchor","label":"Stabilizers","value":"Zero-speed fins"}]'::jsonb, '/images/boats/eternity-hero.jpg', null, true, 6, true, 'Eternity 44 — Arcadia 85 charter Ibiza', 'Charter Eternity 44, a 27 m Arcadia 85 from IGY Ibiza Marina. 12 guests, solar-assisted, zero-speed stabilizers. From €8,500/day + VAT.'),
  ('georgia-sunseeker-predator-82', 'Georgia', 'Sunseeker Predator 82', 'Refinement and distinction, a yacht that evokes the grace of the sea.', 'Refit 2025 Sunseeker Predator 82 — four en-suites, hydraulic swim platform, and the unmistakable Predator profile.', '24 metres of Sunseeker with a 2025 refit. Two doubles, a twin and a bunkbed cabin make Georgia flexible for families and friends alike, and the MTU diesels deliver a clean 35-knot top end.', 24, 6.5, 12, 8, 4, 'motor_yacht', 'Sunseeker', 2014, 2025, 'Marina Botafoc, Ibiza', 22, 35, '2 × 1,820 hp Diesel MTU', null, '500 l/h', 6050, 7400, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"24.00 m / 6.50 m"},{"label":"Engines","value":"2 × 1,820 hp Diesel MTU"},{"label":"Cruise / max","value":"22 / 35 knots"},{"label":"Consumption","value":"500 l/h"},{"label":"Bathrooms","value":"4 en-suite"},{"label":"Comfort","value":"Generator, A/C, Water maker, Hydraulic platform, Wifi, Bose"}]'::jsonb, '[{"src":"/images/boats/georgia-hero.jpg","alt":"Georgia — Sunseeker Predator 82"}]'::jsonb, '[{"icon":"length","label":"Length","value":"24.00 m"},{"icon":"guests","label":"Guests","value":"12 day · 8 night"},{"icon":"cabins","label":"Cabins","value":"2 doubles + 1 twin + 1 bunk"},{"icon":"speed","label":"Max speed","value":"35 kn"},{"icon":"year","label":"Refit","value":"2025"}]'::jsonb, '/images/boats/georgia-hero.jpg', null, false, 7, true, 'Georgia — Sunseeker Predator 82 charter Ibiza', 'Charter Georgia, a 24 m Sunseeker Predator 82 (refit 2025) from Marina Botafoc. 12 guests, 35 kn. From €6,050/day + VAT.'),
  ('inspiration-pershing-90', 'Inspiration', 'Pershing 90', 'A muse that awakens creativity and happiness on the high seas with its futuristic aesthetics.', 'Pershing 90 at its sharpest — futuristic carbon-tinted lines, four en-suites and a 42-knot top end from twin MTUs.', 'Refit 2025 with an engine overhaul in 2023, Inspiration is the Pershing the Pershing yard wishes every owner kept. Seakeeper stabilization, full audio, and a deck plan built for long Mediterranean afternoons.', 27.42, 6.23, 12, 8, 4, 'motor_yacht', 'Pershing', 2012, 2025, 'Marina Botafoc, Ibiza', 30, 42, '2 × 2,450 hp Diesel MTU', 'Seakeeper', '900 l/h', 10000, 12000, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"27.42 m / 6.23 m"},{"label":"Engines","value":"2 × 2,450 hp Diesel MTU (overhaul 2023)"},{"label":"Cruise / max","value":"30 / 42 knots"},{"label":"Consumption","value":"900 l/h"},{"label":"Stabilizers","value":"Seakeeper"},{"label":"Comfort","value":"Generator, A/C, Water maker, Wifi, Bose surround"}]'::jsonb, '[{"src":"/images/boats/inspiration-hero.jpg","alt":"Inspiration — Pershing 90"}]'::jsonb, '[{"icon":"length","label":"Length","value":"27.42 m"},{"icon":"guests","label":"Guests","value":"12 day · 8 night"},{"icon":"cabins","label":"Cabins","value":"2 doubles + 2 twins"},{"icon":"speed","label":"Max speed","value":"42 kn"},{"icon":"year","label":"Refit","value":"2025"}]'::jsonb, '/images/boats/inspiration-hero.jpg', null, true, 8, true, 'Inspiration — Pershing 90 charter Ibiza', 'Charter Inspiration, a 27.4 m Pershing 90 (refit 2025) from Marina Botafoc. 12 guests, 42 kn. From €10,000/day + VAT.'),
  ('invictus-riva-rivale-52', 'Invictus', 'Riva Rivale 52', 'Strong and powerful, she defies limits with her invincible spirit.', 'A 2025-refit Riva Rivale 52 — Italian day-boat DNA scaled to a real charter with two cabins and 37-knot capability.', 'The Rivale 52 is the Riva that everyone wants but no one talks about — smaller than the Argo, more agile, with the same hand-finished hull and chrome details. Refit 2025.', 16.12, 4.61, 9, 4, 2, 'motor_yacht', 'Riva', 2008, 2025, 'Marina Botafoc, Ibiza', 24, 37, '2 × 900 hp Diesel MAN', null, '250 l/h', 2750, 3200, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"16.12 m / 4.61 m"},{"label":"Engines","value":"2 × 900 hp Diesel MAN"},{"label":"Cruise / max","value":"24 / 37 knots"},{"label":"Consumption","value":"250 l/h"},{"label":"Bathrooms","value":"2 en-suite"},{"label":"Comfort","value":"Generator, A/C, Wifi, Bose surround"}]'::jsonb, '[{"src":"/images/boats/invictus-hero.jpg","alt":"Invictus — Riva Rivale 52"}]'::jsonb, '[{"icon":"length","label":"Length","value":"16.12 m"},{"icon":"guests","label":"Guests","value":"9 day · 4 night"},{"icon":"cabins","label":"Cabins","value":"2 doubles"},{"icon":"speed","label":"Max speed","value":"37 kn"},{"icon":"year","label":"Refit","value":"2025"}]'::jsonb, '/images/boats/invictus-hero.jpg', null, false, 9, true, 'Invictus — Riva Rivale 52 charter Ibiza', 'Charter Invictus, a Riva Rivale 52 (refit 2025) from Marina Botafoc. 16 m, 37 kn, two doubles. From €2,750/day + VAT.'),
  ('mazu-astondoa-80', 'Mazu', 'Astondoa 80', 'Sailing with strength and dominance, captivating all those she encounters.', 'Astondoa 80 with a 2025 refit and brand-new engines in 2024 — a Spanish flagship reborn for the Ibiza season.', 'Two doubles, two twins, four en-suite bathrooms, a brand-new generator and air conditioning, hydraulic platform and water maker. Mazu is a serious cruiser at a sensible price for 24 metres of yacht.', 24.5, 5.4, 12, 8, 4, 'motor_yacht', 'Astondoa', 2010, 2025, 'Marina Botafoc, Ibiza', 18, 24, '2 × 1,200 hp Diesel MAN (new 2024)', null, '300 l/h', 3950, 5300, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"24.50 m / 5.40 m"},{"label":"Engines","value":"2 × 1,200 hp Diesel MAN (new 2024)"},{"label":"Cruise / max","value":"18 / 24 knots"},{"label":"Consumption","value":"300 l/h"},{"label":"Bathrooms","value":"4 en-suite"},{"label":"Comfort","value":"Brand-new Generator & A/C, Water maker, Hydraulic platform, Wifi, Bose"}]'::jsonb, '[{"src":"/images/boats/mazu-hero.jpg","alt":"Mazu — Astondoa 80"}]'::jsonb, '[{"icon":"length","label":"Length","value":"24.50 m"},{"icon":"guests","label":"Guests","value":"12 day · 8 night"},{"icon":"cabins","label":"Cabins","value":"2 doubles + 2 twins"},{"icon":"speed","label":"Max speed","value":"24 kn"},{"icon":"year","label":"Refit","value":"2025 · new engines 2024"}]'::jsonb, '/images/boats/mazu-hero.jpg', null, false, 10, true, 'Mazu — Astondoa 80 charter Ibiza', 'Charter Mazu, a 24.5 m Astondoa 80 (refit 2025, new engines 2024) from Marina Botafoc. From €3,950/day + VAT.'),
  ('number-9-sunseeker-predator-72', 'Number 9', 'Sunseeker Predator 72', 'Sporty and elegant lines offering a captivating experience.', 'A refit-2025 Predator 72 — three cabins, hydraulic platform, and the Sunseeker silhouette at one of the fleet''s friendlier price points.', '22 metres, three fully-equipped bathrooms, MAN diesels and a 35-knot top end. Number 9 is a strong choice for groups stepping up from a day boat into a proper sport yacht.', 22.25, 5.4, 12, 6, 3, 'motor_yacht', 'Sunseeker', 2010, 2025, 'Marina Botafoc, Ibiza', 22, 35, '2 × 1,550 hp Diesel MAN', null, '350 l/h', 4700, 6000, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"22.25 m / 5.40 m"},{"label":"Engines","value":"2 × 1,550 hp Diesel MAN"},{"label":"Cruise / max","value":"22 / 35 knots"},{"label":"Consumption","value":"350 l/h"},{"label":"Bathrooms","value":"3 fully equipped"},{"label":"Comfort","value":"Generator, A/C, Water maker, Hydraulic platform, Wifi, Bose"}]'::jsonb, '[{"src":"/images/boats/no9-hero.jpg","alt":"Number 9 — Sunseeker Predator 72"}]'::jsonb, '[{"icon":"length","label":"Length","value":"22.25 m"},{"icon":"guests","label":"Guests","value":"12 day · 6 night"},{"icon":"cabins","label":"Cabins","value":"2 doubles + 1 twin"},{"icon":"speed","label":"Max speed","value":"35 kn"},{"icon":"year","label":"Refit","value":"2025"}]'::jsonb, '/images/boats/no9-hero.jpg', null, false, 11, true, 'Number 9 — Sunseeker Predator 72 charter Ibiza', 'Charter Number 9, a 22 m Sunseeker Predator 72 (refit 2025) from Marina Botafoc. 12 guests, 35 kn. From €4,700/day + VAT.'),
  ('ruby-tuesday-princess-v72', 'Ruby Tuesday', 'Princess V72', 'The epitome of luxury and passion that captivates everyone.', 'Princess V72 with a 2022 refit and Caterpillar diesels — 22 metres, three en-suites, hydraulic platform, water maker.', 'Ruby Tuesday is a Princess at her best: three guest cabins, sociable cockpit, full audio system and a 39-knot top end when the moment calls for it.', 22, 5.2, 12, 6, 3, 'motor_yacht', 'Princess', 2014, 2022, 'Marina Botafoc, Ibiza', 23, 39, '2 × 1,800 hp Diesel Caterpillar', null, '400 l/h', 5450, 6800, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"22.00 m / 5.20 m"},{"label":"Engines","value":"2 × 1,800 hp Diesel Caterpillar"},{"label":"Cruise / max","value":"23 / 39 knots"},{"label":"Consumption","value":"400 l/h"},{"label":"Bathrooms","value":"3 en-suite"},{"label":"Comfort","value":"Generator, A/C, Water maker, Hydraulic platform, Wifi, Bose"}]'::jsonb, '[{"src":"/images/boats/ruby-tuesday-hero.jpg","alt":"Ruby Tuesday — Princess V72"}]'::jsonb, '[{"icon":"length","label":"Length","value":"22.00 m"},{"icon":"guests","label":"Guests","value":"12 day · 6 night"},{"icon":"cabins","label":"Cabins","value":"2 doubles + 1 twin"},{"icon":"speed","label":"Max speed","value":"39 kn"},{"icon":"year","label":"Refit","value":"2022"}]'::jsonb, '/images/boats/ruby-tuesday-hero.jpg', null, true, 12, true, 'Ruby Tuesday — Princess V72 charter Ibiza', 'Charter Ruby Tuesday, a 22 m Princess V72 (refit 2022) from Marina Botafoc. 12 guests, 39 kn. From €5,450/day + VAT.'),
  ('sensation-pershing-72', 'Sensation', 'Pershing 72', 'An experience of intense and pleasurable emotions at sea.', 'A 35-knot cruise from a 22-metre Pershing — refit 2023, twin MTU 2,000 hp, three en-suites, water maker.', 'Sensation is one of the faster boats in the fleet at a 35-knot cruise. Pershing''s signature low silhouette, three guest cabins below and a 40-knot top end make her the right call for groups that want to actually use the throttle.', 22.26, 5.5, 12, 6, 3, 'motor_yacht', 'Pershing', 2012, 2023, 'Marina Botafoc, Ibiza', 35, 40, '2 × 2,000 hp Diesel MTU', null, '600 l/h', 5900, 7100, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"22.26 m / 5.50 m"},{"label":"Engines","value":"2 × 2,000 hp Diesel MTU"},{"label":"Cruise / max","value":"35 / 40 knots"},{"label":"Consumption","value":"600 l/h"},{"label":"Bathrooms","value":"3 en-suite"},{"label":"Comfort","value":"Generator, A/C, Water maker, Wifi, Bose surround"}]'::jsonb, '[{"src":"/images/boats/sensation-hero.jpg","alt":"Sensation — Pershing 72"}]'::jsonb, '[{"icon":"length","label":"Length","value":"22.26 m"},{"icon":"guests","label":"Guests","value":"12 day · 6 night"},{"icon":"cabins","label":"Cabins","value":"2 doubles + 1 twin"},{"icon":"speed","label":"Cruise / max","value":"35 / 40 kn"},{"icon":"year","label":"Refit","value":"2023"}]'::jsonb, '/images/boats/sensation-hero.jpg', null, false, 13, true, 'Sensation — Pershing 72 charter Ibiza', 'Charter Sensation, a 22 m Pershing 72 (refit 2023) from Marina Botafoc. 12 guests, 40 kn. From €5,900/day + VAT.'),
  ('tranquility-iii-sunseeker-predator-68', 'Tranquility III', 'Sunseeker Predator 68', 'A unique and relaxing stillness, peace and serenity at its best.', 'A 21-metre Sunseeker Predator 68 — refit 2022 with an engine overhaul, hydraulic platform and water maker.', 'Two double cabins below, both en-suite, MAN diesels at 1,300 hp each, and the Predator hull''s well-known balance between low-speed comfort and a 38-knot top end.', 21.6, 5.21, 12, 4, 2, 'motor_yacht', 'Sunseeker', 2010, 2022, 'Marina Botafoc, Ibiza', 22, 38, '2 × 1,300 hp Diesel MAN (overhaul 2022)', null, '300 l/h', 4150, 5500, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"21.60 m / 5.21 m"},{"label":"Engines","value":"2 × 1,300 hp Diesel MAN (overhaul 2022)"},{"label":"Cruise / max","value":"22 / 38 knots"},{"label":"Consumption","value":"300 l/h"},{"label":"Bathrooms","value":"2 en-suite"},{"label":"Comfort","value":"Generator, A/C, Water maker, Hydraulic platform, Wifi, Bose"}]'::jsonb, '[{"src":"/images/boats/tranquility-hero.jpg","alt":"Tranquility III — Sunseeker Predator 68"}]'::jsonb, '[{"icon":"length","label":"Length","value":"21.60 m"},{"icon":"guests","label":"Guests","value":"12 day · 4 night"},{"icon":"cabins","label":"Cabins","value":"2 doubles"},{"icon":"speed","label":"Max speed","value":"38 kn"},{"icon":"year","label":"Refit","value":"2022"}]'::jsonb, '/images/boats/tranquility-hero.jpg', null, false, 14, true, 'Tranquility III — Sunseeker Predator 68 charter Ibiza', 'Charter Tranquility III, a 21.6 m Sunseeker Predator 68 (refit 2022) from Marina Botafoc. 12 guests, 38 kn. From €4,150/day + VAT.'),
  ('yolo-sunreef-70', 'Yolo', 'Sunreef 70+', 'A call to live every moment with the intensity of the waves.', 'Owner-built 2022 Sunreef 70+ sailing catamaran — Starlink, 39 kW of solar, a 50 m² flybridge and four en-suite doubles.', '23.6 metres, 11 metres of beam, four double cabins all en-suite, a 50 m² flybridge and serious bluewater systems: 1,600-litre water tank, water maker, Mainsail 170 m², Genoa 140 m², Gennaker 340 m² and Staysail 70 m². Quietly the most capable boat in the fleet.', 23.6, 11, 12, 8, 4, 'catamaran', 'Sunreef', 2022, 2024, 'Marina Botafoc, Ibiza', null, null, '2 × 225 hp Diesel John Deere', null, null, 9350, 10500, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"23.60 m / 11.00 m"},{"label":"Engines","value":"2 × 225 hp Diesel John Deere"},{"label":"Generators","value":"2 × 18 kW"},{"label":"Sails","value":"Main 170 m² · Genoa 140 m² · Gennaker 340 m² · Staysail 70 m²"},{"label":"Solar / Water","value":"39 kW solar · 1,600 L fresh water · Water maker"},{"label":"Comfort","value":"Starlink wifi, Bowers & Wilkins audio"}]'::jsonb, '[{"src":"/images/boats/yolo-hero.jpg","alt":"Yolo — Sunreef 70+ sailing catamaran"}]'::jsonb, '[{"icon":"length","label":"Length / Beam","value":"23.60 m / 11 m"},{"icon":"guests","label":"Guests","value":"12 day · 8 night"},{"icon":"cabins","label":"Cabins","value":"4 doubles, all en-suite"},{"icon":"anchor","label":"Sail area","value":"170 m² main · 340 m² gennaker"},{"icon":"year","label":"Year","value":"2022 · refit 2024"}]'::jsonb, '/images/boats/yolo-hero.jpg', null, true, 15, true, 'Yolo — Sunreef 70+ sailing catamaran charter Ibiza', 'Charter Yolo, an owner-built 2022 Sunreef 70+ from Marina Botafoc. 23.6 m, 11 m beam, 4 doubles, Starlink, 39 kW solar. From €9,350/day + VAT.'),
  ('black-jax-sunseeker-predator-74', 'Black Jax', 'Sunseeker Predator 74', 'Elegant, classic, versatile — the highest representation of quality and exceptionality.', 'Like the colour she embodies, Black Jax is the definition of class and timeless fashion. Bold design, intimidating profile, deep black that reflects the water.', '22.4 metres of Sunseeker Predator finished in deep black — three en-suite cabins below, twin 1,850 hp MAN diesels and a 22-knot cruise. Refit 2023.', 22.38, 5.4, 12, 6, 3, 'motor_yacht', 'Sunseeker', 2010, 2023, 'Marina Botafoc, Ibiza', 22, null, '2 × 1,850 hp Diesel MAN', null, null, 5500, null, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"22.38 m / 5.40 m"},{"label":"Engines","value":"2 × 1,850 hp Diesel MAN"},{"label":"Cruise","value":"22 knots"},{"label":"Bathrooms","value":"3 en-suite"},{"label":"Crew","value":"Captain + sailor"},{"label":"Refit","value":"2023"}]'::jsonb, '[{"src":"/images/boats/black-jax-hero.jpg","alt":"Black Jax — Sunseeker Predator 74"}]'::jsonb, '[{"icon":"length","label":"Length","value":"22.38 m"},{"icon":"guests","label":"Guests","value":"12 day · 6 night"},{"icon":"cabins","label":"Cabins","value":"2 doubles + 1 twin"},{"icon":"speed","label":"Cruise","value":"22 kn"},{"icon":"year","label":"Refit","value":"2023"}]'::jsonb, '/images/boats/black-jax-hero.jpg', null, false, 16, true, 'Black Jax — Sunseeker Predator 74 charter Ibiza', 'Charter Black Jax, a 22.4 m Sunseeker Predator 74 in deep black (refit 2023) from Marina Botafoc. 12 guests, 22 kn cruise.'),
  ('django-noah-29fb', 'Django', 'Noah 29FB', 'A gateway to exploring remote places with style and functionality.', 'A high-performance RIB built for coastal adventures, family outings, or as a tender for larger yachts.', '9.4 metres of agile Italian RIB — twin 168 hp Volvo diesels, 22-knot cruise, one bathroom, captain on board. Ideal for fast island-hopping when you don''t need a full motor yacht.', 9.4, 3.25, 9, null, 0, 'day_boat', 'Noah', 2018, 2022, 'Marina Botafoc, Ibiza', 22, null, '2 × 168 hp Diesel Volvo', null, null, 1600, null, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"9.40 m / 3.25 m"},{"label":"Engines","value":"2 × 168 hp Diesel Volvo"},{"label":"Cruise","value":"22 knots"},{"label":"Bathrooms","value":"1"},{"label":"Crew","value":"Captain"},{"label":"Style","value":"Performance RIB"}]'::jsonb, '[{"src":"/images/boats/django-hero.jpg","alt":"Django — Noah 29FB RIB"}]'::jsonb, '[{"icon":"length","label":"Length","value":"9.40 m"},{"icon":"guests","label":"Guests","value":"9 day"},{"icon":"bathrooms","label":"Bathrooms","value":"1"},{"icon":"speed","label":"Cruise","value":"22 kn"},{"icon":"year","label":"Refit","value":"2022"}]'::jsonb, '/images/boats/django-hero.jpg', null, false, 17, true, 'Django — Noah 29FB RIB charter Ibiza', 'Charter Django, a 9.4 m Noah 29FB performance RIB from Marina Botafoc. 9 guests, 22 kn, ideal for fast island hops.'),
  ('floppy-sacs-stratos-42', 'Floppy', 'Sacs Stratos 42', 'Where every moment becomes a tribute to freedom and connection with the sea.', 'Floppy isn''t just a RIB — she''s your passport to the wild side of Ibiza, where elegance meets adrenaline on the open sea.', '12.4 metres of Sacs Stratos 42 — one of the most refined maxi-RIBs on the market. Open layout for eleven guests, one cabin, one bathroom, twin Volvo diesels at 168 hp.', 12.4, 3.62, 11, null, 1, 'day_boat', 'Sacs', 2020, 2022, 'Marina Botafoc, Ibiza', 22, null, '2 × 168 hp Diesel Volvo', null, null, 2200, null, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"12.40 m / 3.62 m"},{"label":"Engines","value":"2 × 168 hp Diesel Volvo"},{"label":"Cruise","value":"22 knots"},{"label":"Bathrooms","value":"1"},{"label":"Crew","value":"Captain"},{"label":"Style","value":"Maxi-RIB"}]'::jsonb, '[{"src":"/images/boats/floppy-hero.jpg","alt":"Floppy — Sacs Stratos 42 maxi-RIB"}]'::jsonb, '[{"icon":"length","label":"Length","value":"12.40 m"},{"icon":"guests","label":"Guests","value":"11 day"},{"icon":"cabins","label":"Layout","value":"Open + 1 cabin"},{"icon":"speed","label":"Cruise","value":"22 kn"},{"icon":"year","label":"Refit","value":"2022"}]'::jsonb, '/images/boats/floppy-hero.jpg', null, false, 18, true, 'Floppy — Sacs Stratos 42 maxi-RIB charter Ibiza', 'Charter Floppy, a 12.4 m Sacs Stratos 42 maxi-RIB from Marina Botafoc. 11 guests, 22 kn cruise. Elegance meets adrenaline.'),
  ('majestic-vandutch-40', 'Majestic', 'VanDutch 40', 'A refined boat to sail with elegance and sophistication.', 'Majestic is the embodiment of grandeur at sea — a perfect fusion of elegance and power that inspires both admiration and respect.', '12 metres of unmistakable VanDutch silhouette — clean Dutch lines, twin 480 hp Yanmar diesels and a 22-knot cruise. A day boat made to be seen, with a single open cabin below and a single bathroom.', 11.98, 3.5, 9, null, 1, 'day_boat', 'VanDutch', 2015, 2022, 'Marina Botafoc, Ibiza', 22, null, '2 × 480 hp Diesel Yanmar', null, null, 2400, null, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"11.98 m / 3.50 m"},{"label":"Engines","value":"2 × 480 hp Diesel Yanmar"},{"label":"Cruise","value":"22 knots"},{"label":"Bathrooms","value":"1"},{"label":"Crew","value":"Captain"},{"label":"Style","value":"VanDutch day boat"}]'::jsonb, '[{"src":"/images/boats/majestic-hero.jpg","alt":"Majestic — VanDutch 40"}]'::jsonb, '[{"icon":"length","label":"Length","value":"11.98 m"},{"icon":"guests","label":"Guests","value":"9 day"},{"icon":"cabins","label":"Layout","value":"Open cabin + sofa"},{"icon":"speed","label":"Cruise","value":"22 kn"},{"icon":"year","label":"Refit","value":"2022"}]'::jsonb, '/images/boats/majestic-hero.jpg', null, false, 19, true, 'Majestic — VanDutch 40 charter Ibiza', 'Charter Majestic, a 12 m VanDutch 40 day boat from Marina Botafoc. 9 guests, 22 kn, Dutch lines and Italian Riviera attitude.'),
  ('manbero-ii-princess-v53', 'Manbero II', 'Princess V53', 'An invitation to dance over the waves of the Mediterranean.', 'Princess V53 with an elegant design and adventurous spirit — spacious solarium, open-air areas, the kind of boat made for relaxation and entertainment.', '16.1 metres of Princess V53, refit 2024. One double, one twin and one bunkbed cabin make Manbero II flexible for groups, with twin 1,300 hp MAN diesels for a 22-knot cruise.', 16.12, 4.47, 12, 6, 3, 'motor_yacht', 'Princess', 2010, 2024, 'Marina Botafoc, Ibiza', 22, null, '2 × 1,300 hp Diesel MAN', null, null, 3200, null, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"16.12 m / 4.47 m"},{"label":"Engines","value":"2 × 1,300 hp Diesel MAN"},{"label":"Cruise","value":"22 knots"},{"label":"Bathrooms","value":"2 (1 en-suite)"},{"label":"Crew","value":"Captain"},{"label":"Refit","value":"2024"}]'::jsonb, '[{"src":"/images/boats/manbero-hero.jpg","alt":"Manbero II — Princess V53"}]'::jsonb, '[{"icon":"length","label":"Length","value":"16.12 m"},{"icon":"guests","label":"Guests","value":"12 day · 6 night"},{"icon":"cabins","label":"Cabins","value":"1 double + 1 twin + 1 bunk"},{"icon":"speed","label":"Cruise","value":"22 kn"},{"icon":"year","label":"Refit","value":"2024"}]'::jsonb, '/images/boats/manbero-hero.jpg', null, false, 20, true, 'Manbero II — Princess V53 charter Ibiza', 'Charter Manbero II, a 16 m Princess V53 (refit 2024) from Marina Botafoc. 12 guests, 22 kn cruise, spacious solarium.'),
  ('shaka-laka-princess-v58', 'Shaka Laka', 'Princess V58', 'A name that evokes the sea waves — a design of calm and excellence.', 'Like a wave dancing in the sunlight, Shaka Laka captures the essence of tranquillity and the free spirit of the Hawaiian Shaka gesture.', '18.2 metres of Princess V58 — two doubles and a bunkbed cabin, two en-suite bathrooms, twin 1,070 hp Caterpillar diesels and a 23-knot cruise. Refit 2023.', 18.2, 4.62, 12, 6, 3, 'motor_yacht', 'Princess', 2012, 2023, 'Marina Botafoc, Ibiza', 23, null, '2 × 1,070 hp Diesel CAT', null, null, 3800, null, 'EUR', '["Professional captain & crew","Marina Botafoc base","Snorkel equipment","Towels & sun loungers","Bose / premium sound system","Wifi on board"]'::jsonb, '[{"label":"Length / Beam","value":"18.20 m / 4.62 m"},{"label":"Engines","value":"2 × 1,070 hp Diesel CAT"},{"label":"Cruise","value":"23 knots"},{"label":"Bathrooms","value":"2 en-suite"},{"label":"Crew","value":"Captain"},{"label":"Refit","value":"2023"}]'::jsonb, '[{"src":"/images/boats/shaka-laka-hero.jpg","alt":"Shaka Laka — Princess V58"}]'::jsonb, '[{"icon":"length","label":"Length","value":"18.20 m"},{"icon":"guests","label":"Guests","value":"12 day · 6 night"},{"icon":"cabins","label":"Cabins","value":"2 doubles + 1 bunk"},{"icon":"speed","label":"Cruise","value":"23 kn"},{"icon":"year","label":"Refit","value":"2023"}]'::jsonb, '/images/boats/shaka-laka-hero.jpg', null, false, 21, true, 'Shaka Laka — Princess V58 charter Ibiza', 'Charter Shaka Laka, an 18 m Princess V58 (refit 2023) from Marina Botafoc. 12 guests, 23 kn cruise, two en-suite cabins.');
